INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'environment', 'n.', '/ɪnˈvaɪrənmənt/', '环境;自然环境', 'We should all do something to protect the environment.', '我们都应为保护环境做点事。', 'Protecting the Environment', 1, 0, 'senior', 'wordlist', 'elective3', 'U4', 'protect the environment', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'atmosphere', 'n.', '/ˈætməsfɪə(r)/', '大气;大气层;气氛', 'Too much carbon dioxide in the atmosphere causes the greenhouse effect.', '大气中过多的二氧化碳会引发温室效应。', 'Protecting the Environment', 2, 0, 'senior', 'wordlist', 'elective3', 'U4', 'in the atmosphere', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'carbon', 'n.', '/ˈkɑːbən/', '碳', 'Burning coal and oil releases a great deal of carbon dioxide.', '燃烧煤和石油会释放大量二氧化碳。', 'Protecting the Environment', 3, 0, 'senior', 'wordlist', 'elective3', 'U4', 'carbon dioxide', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'concentration', 'n.', '/ˌkɒnsnˈtreɪʃn/', '浓度;集中;专注', 'The concentration of carbon dioxide in the air is going up steadily.', '空气中二氧化碳的浓度在稳步上升。', 'Protecting the Environment', 4, 0, 'senior', 'wordlist', 'elective3', 'U4', 'the concentration of a gas', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'absorb', 'v.', '/əbˈzɔːb/', '吸收;理解吸收', 'The Earth''s surface absorbs sunlight and is warmed by it.', '地球表面吸收阳光并因此变暖。', 'Protecting the Environment', 5, 0, 'senior', 'wordlist', 'elective3', 'U4', 'absorb heat', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'radiate', 'v.', '/ˈreɪdieɪt/', '辐射;散发', 'At night the Earth cools as it radiates heat into space.', '夜间地球向太空辐射热量而冷却下来。', 'Protecting the Environment', 6, 0, 'senior', 'wordlist', 'elective3', 'U4', 'radiate heat', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'radiation', 'n.', '/ˌreɪdiˈeɪʃn/', '辐射;辐射能', 'Carbon dioxide tends to block the radiation that should leave the Earth.', '二氧化碳往往会阻挡本应离开地球的辐射。', 'Protecting the Environment', 7, 0, 'senior', 'wordlist', 'elective3', 'U4', 'infrared radiation', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'greenhouse', 'n.', '/ˈɡriːnhaʊs/', '温室;暖房', 'Gases like carbon dioxide cause the greenhouse effect.', '二氧化碳等气体会造成温室效应。', 'Protecting the Environment', 8, 0, 'senior', 'wordlist', 'elective3', 'U4', 'the greenhouse effect', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'effect', 'n.', '/ɪˈfekt/', '影响;效果;作用', 'The greenhouse effect has a serious effect on our climate.', '温室效应对我们的气候有严重影响。', 'Protecting the Environment', 9, 0, 'senior', 'wordlist', 'elective3', 'U4', 'have an effect on', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'release', 'v.', '/rɪˈliːs/', '释放;排放;发布', 'Factories release harmful gases into the air every day.', '工厂每天向空气中排放有害气体。', 'Protecting the Environment', 10, 0, 'senior', 'wordlist', 'elective3', 'U4', 'release carbon dioxide', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'emission', 'n.', '/ɪˈmɪʃn/', '排放;排放物', 'Many countries are trying hard to reduce their carbon emissions.', '许多国家正努力减少碳排放。', 'Protecting the Environment', 11, 0, 'senior', 'wordlist', 'elective3', 'U4', 'reduce emissions', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'fuel', 'n.', '/ˈfjuːəl/', '燃料', 'The burning of fossil fuels adds more carbon dioxide to the air.', '燃烧化石燃料会向空气中增加更多二氧化碳。', 'Protecting the Environment', 12, 0, 'senior', 'wordlist', 'elective3', 'U4', 'fossil fuels', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'estimate', 'v.', '/ˈestɪmeɪt/', '估计;估算', 'Scientists estimate that the temperature will keep rising.', '科学家估计气温将持续上升。', 'Protecting the Environment', 13, 0, 'senior', 'wordlist', 'elective3', 'U4', 'it is estimated that', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'quantity', 'n.', '/ˈkwɒntəti/', '数量;量', 'A large quantity of waste enters the ocean every year.', '每年有大量废弃物进入海洋。', 'Protecting the Environment', 14, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a large quantity of', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'widespread', 'adj.', '/ˈwaɪdspred/', '普遍的;广泛的', 'If the food supply drops, starvation will become widespread.', '如果粮食供应减少,饥荒将变得普遍。', 'Protecting the Environment', 15, 0, 'senior', 'wordlist', 'elective3', 'U4', 'widespread damage', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'steadily', 'adv.', '/ˈstedɪli/', '稳定地;持续地', 'The Earth''s average temperature is going up steadily.', '地球的平均气温在稳步上升。', 'Protecting the Environment', 16, 0, 'senior', 'wordlist', 'elective3', 'U4', 'rise steadily', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'upwards', 'adv.', '/ˈʌpwədz/', '向上;上升', 'Each year the level of the gas has moved upwards.', '这种气体的含量每年都在上升。', 'Protecting the Environment', 17, 0, 'senior', 'wordlist', 'elective3', 'U4', 'move upwards', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'decade', 'n.', '/ˈdekeɪd/', '十年', 'In the coming decades the climate may change greatly.', '在未来几十年里气候可能会大幅改变。', 'Protecting the Environment', 18, 0, 'senior', 'wordlist', 'elective3', 'U4', 'in the coming decades', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'mild', 'adj.', '/maɪld/', '(天气)温和的;温和的;不严重的', 'As the planet warms, winters will grow a bit milder.', '随着地球变暖,冬天会变得稍微温和一些。', 'Protecting the Environment', 19, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a mild winter', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'glacier', 'n.', '/ˈɡlæsiə(r)/', '冰川', 'Little by little, the glaciers will retreat as the air gets warmer.', '随着空气变暖,冰川会一点点退缩。', 'Protecting the Environment', 20, 0, 'senior', 'wordlist', 'elective3', 'U4', 'melting glaciers', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'retreat', 'v.', '/rɪˈtriːt/', '退去;后退;撤退', 'Scientists have watched the ice retreat year after year.', '科学家年复一年地看着冰退去。', 'Protecting the Environment', 21, 0, 'senior', 'wordlist', 'elective3', 'U4', 'the ice retreats', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'polar', 'adj.', '/ˈpəʊlə(r)/', '极地的;两极的', 'The polar ice caps have begun to melt because of global warming.', '由于全球变暖,极地冰盖已开始融化。', 'Protecting the Environment', 22, 0, 'senior', 'wordlist', 'elective3', 'U4', 'the polar ice caps', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'demonstrate', 'v.', '/ˈdemənstreɪt/', '证明;说明;演示', 'The melting of the ice caps demonstrates the danger of carbon dioxide.', '冰盖的融化说明了二氧化碳的危险。', 'Protecting the Environment', 23, 0, 'senior', 'wordlist', 'elective3', 'U4', 'demonstrate the danger', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'marine', 'adj.', '/məˈriːn/', '海洋的;海生的', 'Most marine waste is plastic from bottles and packaging.', '大多数海洋垃圾是来自瓶子和包装的塑料。', 'Protecting the Environment', 24, 0, 'senior', 'wordlist', 'elective3', 'U4', 'marine life', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'packaging', 'n.', '/ˈpækɪdʒɪŋ/', '包装;包装材料', 'Buying products with less packaging helps the environment.', '购买包装较少的产品有助于保护环境。', 'Protecting the Environment', 25, 0, 'senior', 'wordlist', 'elective3', 'U4', 'less packaging', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'garbage', 'n.', '/ˈɡɑːbɪdʒ/', '垃圾;废物', 'In many cities, garbage sorting is now part of daily life.', '在许多城市,垃圾分类如今已是日常生活的一部分。', 'Protecting the Environment', 26, 0, 'senior', 'wordlist', 'elective3', 'U4', 'garbage sorting', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'turtle', 'n.', '/ˈtɜːtl/', '海龟', 'Some turtles eat plastic bags because they look like jellyfish.', '一些海龟会吃塑料袋,因为它们看起来像水母。', 'Protecting the Environment', 27, 0, 'senior', 'wordlist', 'elective3', 'U4', 'green turtles', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'jellyfish', 'n.', '/ˈdʒelifɪʃ/', '水母;海蜇', 'To a sea turtle, a floating plastic bag can look like a jellyfish.', '对海龟来说,漂浮的塑料袋看起来像水母。', 'Protecting the Environment', 28, 0, 'senior', 'wordlist', 'elective3', 'U4', 'look like jellyfish', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'block', 'v.', '/blɒk/', '堵塞;阻挡', 'Carbon dioxide can block the heat that should leave the Earth.', '二氧化碳会阻挡本应离开地球的热量。', 'Protecting the Environment', 29, 0, 'senior', 'wordlist', 'elective3', 'U4', 'block the heat', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'poison', 'v.', '/ˈpɔɪzn/', '毒害;使中毒', 'Plastic waste may poison the animals that swallow it.', '塑料垃圾可能毒害吞食它的动物。', 'Protecting the Environment', 30, 0, 'senior', 'wordlist', 'elective3', 'U4', 'poison the animals', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'survey', 'n.', '/ˈsɜːveɪ/', '调查;民意调查', 'A survey showed that half of green turtles eat rubbish.', '一项调查显示,半数绿海龟会吃下垃圾。', 'Protecting the Environment', 31, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a survey shows', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'threaten', 'v.', '/ˈθretn/', '威胁;危及', 'Six species of sea turtle are already threatened with extinction.', '六种海龟已濒临灭绝。', 'Protecting the Environment', 32, 0, 'senior', 'wordlist', 'elective3', 'U4', 'be threatened with', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'sustain', 'v.', '/səˈsteɪn/', '维持;支撑;供养', 'The ocean sustains us with the basic elements of life.', '海洋以生命的基本要素维持着我们。', 'Protecting the Environment', 33, 0, 'senior', 'wordlist', 'elective3', 'U4', 'sustain life', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'sustainable', 'adj.', '/səˈsteɪnəbl/', '可持续的', 'Using less is a step towards more sustainable development.', '少用一些是迈向更可持续发展的一步。', 'Protecting the Environment', 34, 0, 'senior', 'wordlist', 'elective3', 'U4', 'sustainable development', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'element', 'n.', '/ˈelɪmənt/', '要素;基本部分;元素', 'Clean water and air are basic elements of life.', '洁净的水和空气是生命的基本要素。', 'Protecting the Environment', 35, 0, 'senior', 'wordlist', 'elective3', 'U4', 'the basic elements', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'cycle', 'n.', '/ˈsaɪkl/', '循环;周期', 'The ocean is an essential part of the water cycle.', '海洋是水循环中不可或缺的一部分。', 'Protecting the Environment', 36, 0, 'senior', 'wordlist', 'elective3', 'U4', 'the water cycle', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'trap', 'v.', '/træp/', '使陷入困境;困住', 'Sea animals can become trapped in rubbish floating in the water.', '海洋动物可能被漂在水中的垃圾困住。', 'Protecting the Environment', 37, 0, 'senior', 'wordlist', 'elective3', 'U4', 'be trapped in', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'consequence', 'n.', '/ˈkɒnsɪkwəns/', '结果;后果', 'The rising sea level is one serious consequence of global warming.', '海平面上升是全球变暖的一个严重后果。', 'Protecting the Environment', 38, 0, 'senior', 'wordlist', 'elective3', 'U4', 'the consequences of', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'environmentalist', 'n.', '/ɪnˌvaɪrənˈmentəlɪst/', '环境保护论者;环保人士', 'The young environmentalist decided to save the rainforest.', '这位年轻的环保人士决定拯救雨林。', 'Protecting the Environment', 39, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a young environmentalist', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'significance', 'n.', '/sɪɡˈnɪfɪkəns/', '重要性;意义', 'Few people understand the significance of the rainforests to the Earth.', '很少有人理解雨林对地球的重要性。', 'Protecting the Environment', 40, 0, 'senior', 'wordlist', 'elective3', 'U4', 'the significance of', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'profit', 'n.', '/ˈprɒfɪt/', '利润;收益', 'They set up a non-profit group to protect the forest.', '他们成立了一个非营利组织来保护森林。', 'Protecting the Environment', 41, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a non-profit group', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'honourable', 'adj.', '/ˈɒnərəbl/', '可敬的;值得钦佩的', 'Saving the rainforest is a difficult but honourable task.', '拯救雨林是一项艰难却可敬的任务。', 'Protecting the Environment', 42, 0, 'senior', 'wordlist', 'elective3', 'U4', 'an honourable task', '美式拼 honorable;美音 /ˈɑːnərəbl/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'optimistic', 'adj.', '/ˌɒptɪˈmɪstɪk/', '乐观的', 'She is optimistic that people can still save the planet together.', '她乐观地认为人们仍能齐心拯救地球。', 'Protecting the Environment', 43, 0, 'senior', 'wordlist', 'elective3', 'U4', 'feel optimistic', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'pessimistic', 'adj.', '/ˌpesɪˈmɪstɪk/', '悲观的', 'Some people are pessimistic about the future of the climate.', '有些人对气候的未来持悲观态度。', 'Protecting the Environment', 44, 0, 'senior', 'wordlist', 'elective3', 'U4', 'be pessimistic about', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'neutral', 'adj.', '/ˈnjuːtrəl/', '中立的;持平的', 'The speaker stayed neutral and did not take either side.', '演讲者保持中立,不偏向任何一方。', 'Protecting the Environment', 45, 0, 'senior', 'wordlist', 'elective3', 'U4', 'stay neutral', '美音 /ˈnuːtrəl/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bin', 'n.', '/bɪn/', '垃圾箱;垃圾桶', 'Make sure you use a recycle bin every time.', '务必每次都使用回收箱。', 'Protecting the Environment', 46, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a recycle bin', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'extreme', 'adj.', '/ɪkˈstriːm/', '极端的;极度的', 'The Earth may suffer from extreme weather more often.', '地球可能会更频繁地遭受极端天气。', 'Protecting the Environment', 47, 0, 'senior', 'wordlist', 'elective3', 'U4', 'extreme weather', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'global', 'adj.', '/ˈɡləʊbl/', '全球的;全世界的', 'Global warming is one of the biggest problems we face today.', '全球变暖是我们当今面临的最大问题之一。', 'Protecting the Environment', 48, 0, 'senior', 'wordlist', 'elective3', 'U4', 'global warming', NULL, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se3u4.01', '①强调句连接词:强调人用 who,强调物/事用 that', 'A2', 12, '上外版选择性必修第三册 U4 — It is/was + 被强调部分 + that/who…。被强调的是人(指人的成分)时连接词用 who;被强调的是物或事情时一律用 that,不能用 which。', 1, 'elective3', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se3u4.02', '②强调状语(时间/地点/原因/方式):连接词仍用 that', 'A2', 12, '上外版选择性必修第三册 U4 — 强调句强调时间、地点、原因、方式等状语时,连接词都用 that,而不用普通定语从句里的 when/where/why——这正是强调句与定语从句的区别。', 2, 'elective3', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se3u4.03', '③It was not until … that … 与强调一般疑问句/强调主语', 'A2', 12, '上外版选择性必修第三册 U4 — It was not until + 时间/事件 + that + 主句(直到……才……);一般疑问句强调用 Is/Was it + 被强调部分 + that/who…;强调作主语的人仍用 who。', 3, 'elective3', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.01'), 'It was Dr Lin ____ first warned the village about the rising sea.', 'who', 'which', 'what', 'whom', 'A', '强调句强调的是人 Dr Lin,且在从句中作主语,连接词用 who。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.01'), 'It is the volunteers ____ clean the beach every single weekend.', 'which', 'who', 'what', 'whom', 'B', '被强调部分 the volunteers 指人,强调句连接词用 who。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.01'), 'It was Janine ____ decided to save the rainforest in Costa Rica.', 'which', 'what', 'who', 'whose', 'C', '强调的是人 Janine,用 who 引导强调句。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.01'), 'It is ordinary people ____ can make the biggest difference to the planet.', 'which', 'what', 'whom', 'who', 'D', '被强调部分 ordinary people 指人,连接词用 who。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.01'), 'It was my grandmother ____ taught me to sort the rubbish at home.', 'who', 'which', 'what', 'whose', 'A', '强调的是人 my grandmother,强调句用 who。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.01'), 'It is scientists ____ have measured the carbon dioxide for many years.', 'which', 'who', 'what', 'whom', 'B', '被强调部分 scientists 指人,连接词用 who。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.01'), 'It was a young environmentalist ____ started the whole clean-up project.', 'which', 'what', 'who', 'whom', 'C', '强调的是人,且作从句主语,用 who。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.01'), 'It is the students ____ planted those young trees along the river.', 'which', 'what', 'whose', 'who', 'D', '被强调部分 the students 指人,强调句用 who。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.01'), 'It was Tom and Lily ____ organised the recycling drive at our school.', 'who', 'which', 'what', 'whom', 'A', '强调的是人 Tom and Lily,连接词用 who。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.01'), 'It is all of us ____ should take care of the Earth, not just the government.', 'which', 'who', 'what', 'whom', 'B', '被强调部分 all of us 指人,用 who 引导强调句。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.01'), 'It was carbon dioxide ____ the plants needed in order to produce food.', 'who', 'which', 'that', 'what', 'C', '被强调部分 carbon dioxide 指物,强调句一律用 that,不用 which。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.01'), 'It is the greenhouse effect ____ keeps the Earth warm enough for life.', 'who', 'which', 'what', 'that', 'D', '强调的是事物 the greenhouse effect,连接词用 that。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.01'), 'It was the melting of the ice caps ____ worried the scientists most.', 'that', 'who', 'which', 'what', 'A', '被强调部分指事情,强调句用 that,不用 which。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.01'), 'It is plastic waste ____ causes the most harm to sea animals.', 'who', 'that', 'which', 'what', 'B', '强调的是物 plastic waste,连接词用 that。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.01'), 'It was the burning of fossil fuels ____ released so much carbon dioxide.', 'who', 'which', 'that', 'what', 'C', '被强调部分指事情,强调句一律用 that。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.01'), 'It is clean energy ____ many countries are turning to these days.', 'who', 'which', 'what', 'that', 'D', '强调的是物 clean energy,连接词用 that,不用 which。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.01'), 'It was a small habit ____ changed the way our whole family lives.', 'that', 'who', 'which', 'what', 'A', '被强调部分 a small habit 指物,强调句用 that。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.01'), 'It is the ocean ____ produces about half of the oxygen we breathe.', 'who', 'that', 'which', 'what', 'B', '强调的是事物 the ocean,连接词用 that。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.01'), 'It was the rising temperature ____ made the glaciers slowly retreat.', 'who', 'which', 'that', 'what', 'C', '被强调部分指事物,强调句一律用 that,不用 which。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.01'), 'It is the rubbish left on the beaches ____ finally flows into the sea.', 'who', 'which', 'what', 'that', 'D', '强调的是物 the rubbish,连接词用 that。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.02'), 'It was in 1958 ____ the carbon dioxide in the air was first measured carefully.', 'that', 'when', 'where', 'which', 'A', '强调句强调时间状语 in 1958,连接词用 that,不用 when。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.02'), 'It is in the polar regions ____ the effects of warming show up first.', 'where', 'that', 'when', 'which', 'B', '强调地点状语 in the polar regions,强调句用 that,不用 where。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.02'), 'It was because of human activity ____ too much carbon dioxide built up.', 'why', 'when', 'that', 'where', 'C', '强调原因状语 because of human activity,连接词用 that,不用 why。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.02'), 'It is on the beaches ____ most of the plastic rubbish finally ends up.', 'where', 'when', 'which', 'that', 'D', '强调地点状语 on the beaches,强调句用 that。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.02'), 'It was step by step ____ the family slowly reduced its carbon footprint.', 'that', 'which', 'when', 'where', 'A', '强调方式状语 step by step,连接词用 that。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.02'), 'It is at night ____ the Earth loses heat by radiating it into space.', 'when', 'that', 'where', 'why', 'B', '强调时间状语 at night,强调句用 that,不用 when。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.02'), 'It was in Costa Rica ____ the young environmentalist saved a rainforest.', 'where', 'when', 'that', 'which', 'C', '强调地点状语 in Costa Rica,连接词用 that,不用 where。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.02'), 'It is only with everyone''s help ____ we can really slow global warming.', 'which', 'when', 'where', 'that', 'D', '强调方式/条件状语,强调句用 that。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.02'), 'It was during the last century ____ the forests began to disappear quickly.', 'that', 'when', 'where', 'which', 'A', '强调时间状语 during the last century,连接词用 that。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.02'), 'It is in the huge Antarctic ice cap ____ most of the world''s ice is found.', 'where', 'that', 'when', 'which', 'B', '强调地点状语,强调句用 that,不用 where。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.02'), 'It was for this reason ____ the school decided to start a recycling project.', 'why', 'when', 'that', 'which', 'C', '强调原因状语 for this reason,连接词用 that,不用 why。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.02'), 'It is by saving energy at home ____ each of us can help the planet.', 'which', 'when', 'where', 'that', 'D', '强调方式状语 by saving energy,强调句用 that。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.02'), 'It was after the survey ____ people realised how serious the problem was.', 'that', 'when', 'where', 'which', 'A', '强调时间状语 after the survey,连接词用 that。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.02'), 'It is near the equator ____ many dry areas now suffer long droughts.', 'where', 'that', 'when', 'which', 'B', '强调地点状语 near the equator,强调句用 that,不用 where。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.02'), 'It was little by little ____ the sea level began to rise along the coast.', 'which', 'when', 'that', 'where', 'C', '强调方式状语 little by little,连接词用 that。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.02'), 'It is every weekend ____ the volunteers gather to clean up the river.', 'when', 'where', 'which', 'that', 'D', '强调时间状语 every weekend,强调句用 that,不用 when。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.02'), 'It was through cutting down forests ____ humans made the problem worse.', 'that', 'which', 'when', 'where', 'A', '强调方式状语,连接词用 that。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.02'), 'It is in the oceans ____ a huge quantity of waste ends up each year.', 'where', 'that', 'when', 'which', 'B', '强调地点状语 in the oceans,强调句用 that,不用 where。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.02'), 'It was not long ago ____ people first heard the words ''carbon footprint''.', 'when', 'where', 'that', 'which', 'C', '强调时间状语 not long ago,连接词用 that。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.02'), 'It is for the sake of our children ____ we must protect the Earth now.', 'why', 'when', 'which', 'that', 'D', '强调原因/目的状语,强调句用 that,不用 why。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.03'), 'It was not until midnight ____ the rescue team reached the flooded village.', 'that', 'when', 'until', 'where', 'A', 'It was not until … that … 是固定的强调结构,空格用 that。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.03'), 'It was not until the ice began to melt ____ people saw the real danger.', 'when', 'that', 'which', 'where', 'B', 'not until 强调结构,主句前用 that。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.03'), 'It was not until 2020 ____ the city finally banned thin plastic bags.', 'when', 'where', 'that', 'which', 'C', 'It was not until + 时间 + that…,空格用 that。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.03'), 'It is not until rubbish is picked up ____ the beach becomes safe again.', 'when', 'which', 'where', 'that', 'D', 'not until 强调结构,连接用 that。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.03'), 'It was not until the forests disappeared ____ less carbon dioxide was removed.', 'that', 'when', 'which', 'where', 'A', 'It was not until … that … 强调,空格用 that。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.03'), 'It was not until the survey came out ____ we understood the whole problem.', 'when', 'that', 'where', 'which', 'B', 'not until 强调结构,用 that 连接主句。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.03'), 'It is not until we act together ____ global warming can really be slowed.', 'when', 'which', 'that', 'where', 'C', 'It is not until … that … 强调,空格用 that。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.03'), 'It was not until last year ____ our school started sorting its waste.', 'when', 'where', 'which', 'that', 'D', 'It was not until + 时间 + that…,空格用 that。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.03'), 'Was it the greenhouse effect ____ caused the temperature to rise so fast?', 'that', 'which', 'what', 'who', 'A', '一般疑问句强调结构 Was it … that …,强调物用 that。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.03'), 'Is it really plastic ____ does the most harm to the sea turtles?', 'which', 'that', 'what', 'who', 'B', '强调句一般疑问形式 Is it … that …,强调物用 that。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.03'), 'Was it carbon dioxide ____ the plants needed to make their own food?', 'which', 'what', 'that', 'who', 'C', 'Was it … that … 强调结构,强调物用 that,不用 which。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.03'), 'Is it clean energy ____ our country is turning to in order to cut emissions?', 'which', 'what', 'who', 'that', 'D', '强调句一般疑问形式,强调物用 that。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.03'), 'It was the volunteers ____ first cleaned up that part of the coast.', 'who', 'which', 'what', 'whom', 'A', '强调作主语的人 the volunteers,连接词用 who。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.03'), 'Is it the young environmentalist ____ leads the rainforest project now?', 'which', 'who', 'what', 'whom', 'B', '强调句一般疑问形式,强调的是人,用 who。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.03'), 'It was only after the flood ____ the town built much higher sea walls.', 'when', 'which', 'that', 'where', 'C', '强调时间状语 only after the flood,连接词用 that。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.03'), 'It was by reducing packaging ____ the shop cut its waste in half.', 'which', 'when', 'where', 'that', 'D', '强调方式状语 by reducing packaging,强调句用 that。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.03'), 'It is the rising sea ____ threatens many low-lying coastal cities today.', 'that', 'who', 'which', 'what', 'A', '强调作主语的事物 the rising sea,连接词用 that,不用 which。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.03'), 'It was the melting glaciers ____ first showed the world the real danger.', 'who', 'that', 'which', 'what', 'B', '强调作主语的事物,强调句用 that。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.03'), 'It is everyone''s small effort ____ adds up to one big change in the end.', 'who', 'which', 'that', 'what', 'C', '强调作主语的事物 everyone''s small effort,连接词用 that。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U4' AND code='se3u4.03'), 'It was not until the air grew dirty ____ the old factory was finally closed.', 'when', 'which', 'where', 'that', 'D', 'It was not until … that … 强调结构,空格用 that。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Villain in the Atmosphere', 'Carbon dioxide is a gas that we breathe out every day, and at first it seems quite harmless. In fact, plants need this gas in order to make their own food. Yet the same gas can act like a quiet villain. Sunlight travels through the atmosphere and warms the surface of the Earth. At night, the Earth cools down again by radiating heat back into space. Carbon dioxide, however, tends to block some of this heat, so the planet keeps more warmth than it really should. This is what people call the greenhouse effect. A small amount of carbon dioxide keeps us comfortably warm, which is a good thing. The trouble is that its concentration in the air has been rising steadily for decades. As factories burn more coal and oil, and as more forests are cut down, more of the gas pours into the atmosphere. Little by little, the average temperature climbs, and the balance that all life depends on is slowly lost.', '说明·温室效应', 164, '[{"q":"Why does the writer say carbon dioxide is not simply harmful?","answer":"A","options":["Plants rely on it to produce their food.","It can be sold for a high price.","It blocks all sunlight from the Earth.","It is never found in the air we breathe."],"explanation":"对应 ''plants need this gas in order to make their own food'' 的转述。"},{"q":"How does carbon dioxide cause the greenhouse effect?","answer":"B","options":["By cooling the Earth''s surface quickly.","By keeping heat that should escape into space.","By stopping plants from growing at all.","By removing oxygen from the atmosphere."],"explanation":"对应 ''tends to block some of this heat… keeps more warmth than it really should'' 的转述。"},{"q":"What is making the amount of carbon dioxide go up?","answer":"A","options":["The burning of fuels and the loss of forests.","Fewer factories and more forests.","Cooler weather in the polar regions.","The slow movement of the glaciers."],"explanation":"对应 ''factories burn more coal and oil, and as more forests are cut down'' 的转述。"}]'::jsonb, '[{"word":"atmosphere","cn":"大气层"},{"word":"radiate","cn":"辐射"},{"word":"concentration","cn":"浓度"}]'::jsonb, 2, 'elective3', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'When the Ice Caps Melt', 'Most of the ice in the world is locked away in two huge ice caps. About ninety percent of it lies in Antarctica, and another eight percent covers Greenland. For a long time, this ice has stayed frozen and still. Now, as the average temperature of the Earth rises, that picture is changing. Winters are growing a little milder and summers a little hotter. Bit by bit, the glaciers retreat and the polar ice caps begin to melt. Scientists say this melting may be the most dangerous change of all. When ice on land turns to water, that water runs into the sea, and so the sea level slowly rises. If the great ice caps melt far enough, the rising water could one day reach deep into low-lying cities along the coast. Streets that are busy today might lie under the sea in the future. That is why so many researchers watch the ice so closely and warn us not to ignore the danger.', '说明·海平面上升', 164, '[{"q":"Where is most of the world''s ice found?","answer":"B","options":["In rivers across Europe.","Mainly in the Antarctic ice cap.","On the tops of small mountains.","Under the streets of coastal cities."],"explanation":"对应 ''About ninety percent of it lies in Antarctica'' 的转述。"},{"q":"Why does the sea level rise as the ice caps melt?","answer":"C","options":["Because ships push the water higher.","Because rain falls much more often.","Because melted ice flows from the land into the sea.","Because the ocean grows colder each year."],"explanation":"对应 ''that water runs into the sea, and so the sea level slowly rises'' 的转述。"},{"q":"What does the writer warn could happen to some coastal cities?","answer":"D","options":["They will all become much colder.","They will lose every river nearby.","They will no longer need any water.","They may one day be covered by the rising sea."],"explanation":"对应 ''Streets that are busy today might lie under the sea in the future'' 的转述。"}]'::jsonb, '[{"word":"glacier","cn":"冰川"},{"word":"retreat","cn":"退去"},{"word":"polar","cn":"极地的"}]'::jsonb, 2, 'elective3', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Together for Our Ocean', 'Every year a huge quantity of waste ends up in the world''s oceans and causes trouble for the animals living there. About eighty percent of all marine waste is plastic from bottles and packaging. When it rains, this rubbish washes into rivers and then flows out to the sea. Some of it sinks, some collects in great floating patches, and the rest is left on beaches. The waste is dangerous because some animals mistake it for food. A floating plastic bag, for example, can look like a jellyfish to a hungry sea turtle. The plastic may block the animal''s stomach so that it starves, or it may even poison it. A survey found that half of all green turtles have eaten rubbish, and that number is still rising. Six kinds of sea turtle are already threatened with extinction. Groups such as Ocean Conservancy now organise clean-up days on thousands of beaches around the world, but they remind us that the real answer is to throw away less in the first place.', '说明·海洋塑料垃圾', 171, '[{"q":"What is most of the rubbish in the ocean made of?","answer":"A","options":["Mostly plastic, such as old drinks bottles.","Glass from windows.","Old metal from ships.","Wood from broken boats."],"explanation":"对应 ''About eighty percent of all marine waste is plastic from bottles and packaging'' 的转述。"},{"q":"Why is plastic waste dangerous to sea turtles?","answer":"B","options":["It makes the water too cold for them.","They may eat it, thinking it is food.","It teaches them to swim too fast.","It frightens them away from the beaches."],"explanation":"对应 ''some animals mistake it for food… look like a jellyfish to a hungry sea turtle'' 的转述。"},{"q":"According to the group, what is the best solution to the problem?","answer":"C","options":["Building more factories near the sea.","Catching all the sea turtles to save them.","Producing and throwing away less waste.","Banning people from visiting any beach."],"explanation":"对应 ''the real answer is to throw away less in the first place'' 的转述。"}]'::jsonb, '[{"word":"marine","cn":"海洋的"},{"word":"jellyfish","cn":"水母"},{"word":"threaten","cn":"威胁"}]'::jsonb, 2, 'elective3', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'A Young Environmentalist', 'Janine was only a teenager when she first travelled to Costa Rica with her family. There she saw something that she could not forget. People were cutting down the rainforest, tree after tree, to sell the wood and clear the land. Janine understood the significance of those forests to the whole planet, for they give us clean air and a home for countless animals. So she made an honourable decision: she would do something to save them. Back home, she and a few friends set up a small non-profit group. They were not after any profit; they only wanted to buy and protect pieces of the forest before they were lost. At first the task seemed almost impossible, and some people were pessimistic about their chances. But Janine stayed optimistic. Year after year, more volunteers joined, and the group slowly grew. Today it protects a large area of rainforest. Janine often says that the most valuable thing she has learned is that even one young person can begin to change the world.', '记叙·年轻环保人士', 172, '[{"q":"What did Janine see in Costa Rica that troubled her?","answer":"D","options":["Animals were attacking the local people.","The sea was rising over the beaches.","Factories were closing one by one.","Local people were destroying the rainforest for wood."],"explanation":"对应 ''People were cutting down the rainforest, tree after tree'' 的转述。"},{"q":"Why did Janine''s group buy parts of the forest?","answer":"A","options":["To protect them before they were destroyed.","To build new houses there.","To make a large profit from the wood.","To turn them into farmland."],"explanation":"对应 ''wanted to buy and protect pieces of the forest before they were lost'' 的转述;且 ''not after any profit''。"},{"q":"What lesson does Janine say she values most?","answer":"B","options":["That saving forests costs very little.","That a single young person can start to make a difference.","That only governments can help nature.","That travelling abroad is always exciting."],"explanation":"对应 ''even one young person can begin to change the world'' 的转述。"}]'::jsonb, '[{"word":"significance","cn":"重要性"},{"word":"non-profit","cn":"非营利的"},{"word":"optimistic","cn":"乐观的"}]'::jsonb, 2, 'elective3', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'What Is a Carbon Footprint?', 'You may have heard people talk about their ''carbon footprint'', but what does the term really mean? A footprint is the mark you leave behind when you walk. In the same way, a carbon footprint is the mark each of us leaves on the environment. To be exact, it is a measure of all the greenhouse gases that our activities send into the air, both directly and indirectly. Every time you switch on a light, ride in a car, or buy a product wrapped in heavy packaging, a little more carbon dioxide is released somewhere. All of these add up to your personal footprint. The larger the footprint, the more you are adding to global warming. The good news is that a footprint can be made smaller. You might take public transport instead of a car, unplug electronics you are not using, or choose local food with less packaging. None of these changes is hard, yet together they tell us something important about how we use the energy of the Earth.', '说明·碳足迹', 171, '[{"q":"What does a carbon footprint measure?","answer":"C","options":["The size of a person''s real footprint.","The amount of food a family eats.","The greenhouse gases caused by what we do.","The number of cars in a city."],"explanation":"对应 ''a measure of all the greenhouse gases that our activities send into the air'' 的转述。"},{"q":"What does a larger footprint mean, according to the text?","answer":"D","options":["A person walks more each day.","A person uses less electricity.","A person buys lighter packaging.","A person is adding more to global warming."],"explanation":"对应 ''The larger the footprint, the more you are adding to global warming'' 的转述。"},{"q":"Which action does the writer suggest to shrink your footprint?","answer":"A","options":["Travelling by bus rather than driving alone.","Leaving the lights on all night.","Buying products with heavier packaging.","Driving everywhere on your own."],"explanation":"对应 ''take public transport instead of a car'' 的转述。"}]'::jsonb, '[{"word":"carbon footprint","cn":"碳足迹"},{"word":"indirectly","cn":"间接地"},{"word":"packaging","cn":"包装"}]'::jsonb, 2, 'elective3', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Small Habits, Big Difference', 'When people hear about global warming and rising seas, they often feel helpless. The problem seems far too big for any one person to solve. Yet the truth is that big changes are built from small habits. Think about the rubbish in your own home. Many cans, bottles and even old electrical goods can be used again instead of being thrown away. If you sort your waste carefully and drop it in a recycle bin, less of it ends up in the sea or buried in the ground. You can also save energy in simple ways: turn off the lights when you leave a room, unplug your phone charger, and walk or cycle for short trips. None of these actions costs much time or money. By themselves they may seem too small to matter, but every effort adds up. If millions of people each make a few green choices every day, the result is enormous. Protecting the environment, after all, is not the job of a few experts; it is something that belongs to each of us.', '议论·个人小行动', 177, '[{"q":"Why do many people feel helpless about global warming?","answer":"B","options":["They have never heard of rising seas.","They think the problem is too big for one person.","They believe experts have already solved it.","They do not produce any rubbish at all."],"explanation":"对应 ''The problem seems far too big for any one person to solve'' 的转述。"},{"q":"What does the writer suggest doing with cans and bottles at home?","answer":"C","options":["Burying them in the garden.","Sending them straight to the sea.","Using them again rather than throwing them out.","Keeping them locked away forever."],"explanation":"对应 ''can be used again instead of being thrown away'' 的转述。"},{"q":"What is the writer''s main message about protecting the environment?","answer":"D","options":["Only a few experts can really help.","Small habits are a waste of effort.","Saving energy costs too much money.","Everyone''s small green choices add up to a big result."],"explanation":"对应 ''every effort adds up… it is something that belongs to each of us'' 的转述。"}]'::jsonb, '[{"word":"recycle bin","cn":"回收箱"},{"word":"sort","cn":"分类"},{"word":"enormous","cn":"巨大的"}]'::jsonb, 2, 'elective3', 'U4', 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U4', 'My Green Diary', 'Last month our teacher asked us to keep a ''green diary'' for thirty days. The (1)____ was simple: write down one small thing you did each day to help the (2)____. On the first day, I turned off the lights whenever I (3)____ a room. On the second day, I carried a cloth bag to the shop so that I would not need any plastic (4)____. Soon I began to (5)____ my own waste at home, dropping cans and bottles into the right (6)____. I also started to walk to school instead of asking my dad to (7)____ me. At first these changes felt too (8)____ to matter. But by the end of the month, my diary was full, and I felt (9)____ of what I had done. I learned that protecting the Earth does not need money or magic; it just needs us to form a few good (10)____ and keep them.', 153, 2, '[{"q":"1","answer":"A","options":["task","song","price","noise"],"explanation":"the task was simple 任务很简单,名词。"},{"q":"2","answer":"B","options":["weather","environment","machine","market"],"explanation":"help the environment 帮助环境。"},{"q":"3","answer":"C","options":["sold","ate","left","lost"],"explanation":"whenever I left a room 每当离开房间,动词。"},{"q":"4","answer":"D","options":["food","music","money","bags"],"explanation":"plastic bags 塑料袋,名词。"},{"q":"5","answer":"A","options":["sort","throw","buy","hide"],"explanation":"sort my own waste 给垃圾分类,动词。"},{"q":"6","answer":"B","options":["price","bin","song","city"],"explanation":"into the right bin 投进正确的垃圾箱,名词。"},{"q":"7","answer":"C","options":["sell","lose","drive","forget"],"explanation":"ask my dad to drive me 让爸爸开车送我,动词。"},{"q":"8","answer":"D","options":["rich","late","busy","small"],"explanation":"too small to matter 太小而无足轻重,形容词。"},{"q":"9","answer":"A","options":["proud","afraid","sorry","bored"],"explanation":"felt proud of 为……感到自豪,形容词。"},{"q":"10","answer":"B","options":["prices","habits","noises","tickets"],"explanation":"a few good habits 一些好习惯,名词。"}]'::jsonb, 1, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U4', 'How the Greenhouse Effect Works', 'Many people have heard of the greenhouse effect, but few really (1)____ how it works. Each day, sunlight (2)____ through the air and warms the ground beneath our feet. After dark, the warm Earth sends this heat back (3)____ the sky. In a healthy world, the heat that comes in by day and (4)____ at night stays in balance. The problem begins when there is too much carbon dioxide in the (5)____. This gas tends to (6)____ part of the heat, so it cannot escape into space. As a (7)____, the planet keeps more warmth than it needs, and its average (8)____ slowly climbs. A little of this effect is (9)____, for without it the Earth would be far too cold for life. Too much of it, however, is (10)____, and that is the danger we must face today.', 139, 2, '[{"q":"1","answer":"C","options":["sell","throw","understand","lose"],"explanation":"understand how it works 理解它如何运作,动词。"},{"q":"2","answer":"D","options":["sells","throws","buys","travels"],"explanation":"sunlight travels through 阳光穿过,动词。"},{"q":"3","answer":"A","options":["into","under","below","across"],"explanation":"back into the sky 回到天空,介词。"},{"q":"4","answer":"B","options":["arrives","leaves","begins","stops"],"explanation":"the heat that … leaves at night 夜间离开,动词。"},{"q":"5","answer":"C","options":["garden","market","atmosphere","machine"],"explanation":"in the atmosphere 在大气中,名词。"},{"q":"6","answer":"D","options":["sell","wash","open","block"],"explanation":"block part of the heat 阻挡部分热量,动词。"},{"q":"7","answer":"A","options":["result","price","song","noise"],"explanation":"as a result 结果,固定搭配。"},{"q":"8","answer":"B","options":["price","temperature","noise","weather"],"explanation":"its average temperature 平均气温,名词。"},{"q":"9","answer":"C","options":["useless","empty","helpful","wrong"],"explanation":"a little of this effect is helpful 有益的,形容词。"},{"q":"10","answer":"D","options":["safe","free","cheap","dangerous"],"explanation":"too much of it is dangerous 危险的,形容词。"}]'::jsonb, 2, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U4', 'Saving the Sea Turtles', 'On a quiet beach in summer, a group of students worked hard to (1)____ the sea turtles. Their teacher had told them a sad (2)____: many turtles die after eating plastic bags, which they (3)____ for jellyfish. The students did not want this to (4)____ near their own home. First, they walked along the sand and (5)____ up every piece of rubbish they could find. Then they put up bright (6)____ to remind visitors to take their litter home. One girl explained that even a single bag could (7)____ a turtle''s stomach and cause it to starve. The work was tiring, and the sun was (8)____, but nobody wanted to stop. By evening, the beach was clean again, and everyone felt (9)____ that they had done something real. They knew that the ocean could not protect itself, so it was up to people to (10)____ after it.', 147, 2, '[{"q":"1","answer":"A","options":["protect","sell","throw","lose"],"explanation":"protect the sea turtles 保护海龟,动词。"},{"q":"2","answer":"B","options":["price","story","noise","machine"],"explanation":"a sad story 一个悲伤的故事,名词。"},{"q":"3","answer":"C","options":["sell","throw","mistake","buy"],"explanation":"mistake … for jellyfish 误认为水母,动词。"},{"q":"4","answer":"D","options":["sleep","leave","buy","happen"],"explanation":"did not want this to happen 不想这发生,动词。"},{"q":"5","answer":"A","options":["picked","sold","lost","hid"],"explanation":"picked up every piece of rubbish 捡起垃圾,动词。"},{"q":"6","answer":"B","options":["foods","signs","prices","songs"],"explanation":"put up bright signs 立起醒目的标牌,名词。"},{"q":"7","answer":"C","options":["open","wash","block","sell"],"explanation":"block a turtle''s stomach 堵住海龟的胃,动词。"},{"q":"8","answer":"D","options":["cold","quiet","empty","hot"],"explanation":"the sun was hot 太阳很烈,形容词。"},{"q":"9","answer":"A","options":["glad","angry","afraid","bored"],"explanation":"felt glad that 感到高兴,形容词。"},{"q":"10","answer":"B","options":["sell","look","throw","give"],"explanation":"look after it 照看它,动词短语 look after。"}]'::jsonb, 3, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U4', 'A Beach Clean-up Day', 'Every spring, our town holds a special (1)____ called Ocean Clean-up Day. Hundreds of (2)____ come to the coast early in the morning, each carrying a bag and a pair of gloves. Their (3)____ is to remove as much rubbish from the beach as they can. If the litter is (4)____ now, it will not flow out to the sea and (5)____ problems for the animals there. Last year I took (6)____ for the first time. I was surprised by how much plastic I found buried in the (7)____. Bottles, cups and broken toys were everywhere. By noon, our small team had (8)____ more than twenty bags. The leader told us that this rubbish would now be (9)____ instead of left in nature. Tired but happy, I understood that one clean beach was only the (10)____; the real goal was to make people produce less waste all year round.', 149, 2, '[{"q":"1","answer":"C","options":["price","noise","event","machine"],"explanation":"a special event 一个特别的活动,名词。"},{"q":"2","answer":"D","options":["prices","machines","songs","volunteers"],"explanation":"Hundreds of volunteers 数百名志愿者,名词。"},{"q":"3","answer":"A","options":["goal","price","noise","song"],"explanation":"their goal is to remove rubbish 目标,名词。"},{"q":"4","answer":"B","options":["sold","collected","lost","bought"],"explanation":"if the litter is collected now 被收集起来,动词(被动)。"},{"q":"5","answer":"C","options":["sell","buy","cause","lose"],"explanation":"cause problems for the animals 给动物带来麻烦,动词。"},{"q":"6","answer":"D","options":["price","noise","song","part"],"explanation":"took part 参加,take part(in)固定搭配。"},{"q":"7","answer":"A","options":["sand","price","noise","song"],"explanation":"buried in the sand 埋在沙子里,名词。"},{"q":"8","answer":"B","options":["sold","filled","lost","thrown"],"explanation":"had filled more than twenty bags 装满了二十多个袋子,动词。"},{"q":"9","answer":"C","options":["eaten","grown","recycled","driven"],"explanation":"would now be recycled 将被回收,动词(被动)。"},{"q":"10","answer":"D","options":["price","noise","song","start"],"explanation":"only the start 仅仅是开始,名词。"}]'::jsonb, 4, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U4', 'The Melting Poles', 'Far to the north and south of the world lie two great fields of ice. For thousands of years they stayed (1)____ and still, deep and white. Today, however, scientists are (2)____. The Earth is slowly growing warmer, and the ice has begun to (3)____. As the temperature (4)____, summers become a little hotter and winters a little milder. Bit by bit, the great glaciers (5)____ towards the mountains, leaving bare rock behind. When ice on the land turns to water, that water flows into the (6)____, and the level of the sea rises. Many low-lying cities along the coast could one day be in (7)____. This is why the melting of the ice is seen as such a serious (8)____. Researchers watch the poles (9)____, hoping the world will act in time. They remind us that the cold, distant ice is closely (10)____ to the lives of people everywhere.', 150, 2, '[{"q":"1","answer":"A","options":["frozen","warm","empty","loud"],"explanation":"stayed frozen and still 保持冰冻,形容词。"},{"q":"2","answer":"B","options":["happy","worried","bored","proud"],"explanation":"scientists are worried 科学家很担忧,形容词。"},{"q":"3","answer":"C","options":["grow","sell","melt","buy"],"explanation":"the ice has begun to melt 冰开始融化,动词。"},{"q":"4","answer":"D","options":["sells","buys","sleeps","rises"],"explanation":"as the temperature rises 随着气温上升,动词。"},{"q":"5","answer":"A","options":["retreat","sing","sell","buy"],"explanation":"the glaciers retreat 冰川退缩,动词。"},{"q":"6","answer":"B","options":["price","sea","noise","song"],"explanation":"flows into the sea 流入大海,名词。"},{"q":"7","answer":"C","options":["price","noise","danger","song"],"explanation":"be in danger 处于危险中,名词。"},{"q":"8","answer":"D","options":["price","noise","song","problem"],"explanation":"such a serious problem 如此严重的问题,名词。"},{"q":"9","answer":"A","options":["closely","loudly","cheaply","sweetly"],"explanation":"watch the poles closely 密切关注,副词。"},{"q":"10","answer":"B","options":["sold","linked","lost","thrown"],"explanation":"closely linked to 与……紧密相连,动词(过去分词)。"}]'::jsonb, 5, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U4', 'Going Green at School', 'This year our Green Club decided to make our school more (1)____ to the environment. We started with a simple (2)____: to cut down the rubbish we produce every day. First, we placed clearly marked (3)____ in every classroom so that students could (4)____ paper, cans and bottles. Next, we asked the canteen to use fewer plastic boxes and more (5)____ that can be washed and used again. We also reminded everyone to (6)____ off the lights and fans when the last person leaves a room, which saves a lot of (7)____. At first, some classmates thought our ideas were too much (8)____. But once they saw how easy the new habits were, more and more of them (9)____ in. By the end of the term, our school had produced far less waste, and we felt that our small club had made a real (10)____.', 145, 2, '[{"q":"1","answer":"C","options":["angry","empty","friendly","loud"],"explanation":"more friendly to the environment 对环境更友好,形容词。"},{"q":"2","answer":"D","options":["price","noise","song","goal"],"explanation":"a simple goal 一个简单的目标,名词。"},{"q":"3","answer":"A","options":["bins","prices","songs","tickets"],"explanation":"clearly marked bins 标记清楚的垃圾箱,名词。"},{"q":"4","answer":"B","options":["sell","sort","eat","lose"],"explanation":"sort paper, cans and bottles 给纸、罐、瓶分类,动词。"},{"q":"5","answer":"C","options":["prices","noises","boxes","songs"],"explanation":"boxes that can be washed and used again 可重复使用的盒子,名词。"},{"q":"6","answer":"D","options":["sell","buy","lose","turn"],"explanation":"turn off the lights 关灯,动词短语 turn off。"},{"q":"7","answer":"A","options":["energy","price","noise","song"],"explanation":"saves a lot of energy 节省大量能源,名词。"},{"q":"8","answer":"B","options":["money","trouble","music","food"],"explanation":"too much trouble 太麻烦,名词。"},{"q":"9","answer":"C","options":["sold","lost","joined","threw"],"explanation":"more of them joined in 加入进来,动词短语 join in。"},{"q":"10","answer":"D","options":["price","noise","song","difference"],"explanation":"made a real difference 带来真正的改变,名词。"}]'::jsonb, 6, 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U4 听力·对话 Planning a Green Project', '上外版选择性必修第三册 U4 · dialogue', 3, 'Mia: Our class needs a green project for this term. Any ideas, Leo?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U4 听力·短文 A Warmer World', '上外版选择性必修第三册 U4 · passage', 2, 'The Earth is slowly getting warmer year after year.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U4 听力·对话 At the Beach Clean-up', '上外版选择性必修第三册 U4 · dialogue', 3, 'Reporter: Good morning! Can you tell us why you organise this clean-up?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U4 听力·短文 Shrink Your Footprint', '上外版选择性必修第三册 U4 · passage', 2, 'Here are a few easy ways to make your carbon footprint smaller.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U4 听力·对话 Optimistic or Not?', '上外版选择性必修第三册 U4 · dialogue', 3, 'Ben: Sometimes I feel the Earth is in real trouble, Anna.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U4 听力·短文 A Message for Young People', '上外版选择性必修第三册 U4 · passage', 2, 'Young people, the future of the planet is partly in your hands.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (12, 'Write a Proposal Letter for the Green Club(为环保社团写一封倡议信)', 'A Proposal Letter for Going Green', '假设你是李华,学校 Green Club(环保社团)的成员。社团即将发起一项''Going Green''活动。请用英语写一封约110-130词的倡议信给全校同学,内容包括:① 指出身边一个环境问题及其后果;② 提出一两条可行的解决办法及期望效果;③ 号召同学们一起行动。注意可适当使用本单元的强调句(It is/was … that …)。', 'Suppose you are Li Hua, a member of your school''s Green Club. The club is launching a ''Going Green'' activity. Write a proposal letter (about 110-130 words) to your schoolmates including: 1) one environmental problem around you and its consequence; 2) one or two practical solutions and the result you expect; 3) a call for everyone to take action. Try to use an emphatic structure (It is/was … that …) where it fits.', '["指出问题与后果(One serious problem is … This means that …)","提出解决办法(Our school can … We students can also …)","说明期望效果(This will lead to … / In this way, …)","号召行动并用强调句(It is all of us that should act now.)"]'::jsonb, 70, 100, 'Dear schoolmates,
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (12, 'elective3', 'U4', '{"title":"强调句 It is/was … that/who … 速查","intro":"想突出句子里的某一部分(常为对比或加强语气),就把它放进框架 It is/was + 被强调部分 + that/who…。判断口诀:去掉 It is/was … that,句子仍然完整通顺,就是强调句。","table":{"headers":["被强调成分","用法 / 例句"],"rows":[["主语(人)","It is the volunteers who clean the beach.(用 who 或 that)"],["主语(物/事)","It is carbon dioxide that plants need.(一律 that)"],["宾语","It is clean energy that we should choose.(用 that)"],["时间/地点/原因状语","It was in 1958 that the gas was first measured.(仍用 that,不用 when/where/why)"],["not until 结构","It was not until midnight that the team arrived.(直到……才……)"]]},"specialRules":[{"rule":"无论强调时间、地点还是原因,连接词都用 that,不用 when/where/why——这是强调句与定语从句最大的区别","mark":"It was here that… √ / It was here where… ✗"},{"rule":"强调的是人,可用 who 或 that;强调物/事只能用 that","mark":"It is Janine who/that started it."},{"rule":"It was not until + 时间/事件 + that + 主句(主句不倒装)","mark":"It was not until he left that I knew."},{"rule":"一般疑问句强调:Is/Was it + 被强调部分 + that/who…?","mark":"Was it CO₂ that the plants needed?"}],"why":["强调句只是给句子加了一层 It is/was … that 的''外壳'',句子本身的成分一个不少;正因为被强调的部分已经被''抽''到 that 前面,that 后面的从句往往会缺一个成分,而连接词只起''连接''作用,所以固定用 that(人用 who),不随被强调成分变化。"],"gaokaoPoints":["that vs when/where/why:看是不是 It is/was … that 强调句,是就用 that;高考语法填空、单选高频。","强调句 vs 定语从句:去掉 It is/was … that 后句子完整=强调句;去掉后不完整、需要先行词=定语从句。","It was not until … that … 的固定搭配与主句不倒装。"],"examVsReal":[{"exam":"It is health that matters most.(考试/书面强调)","real":"Health is what matters most. / Health really matters.","note":"口语里更常用 what-分裂句或加 really、do/does/did 来强调"},{"exam":"It was John who broke the window.(考试)","real":"JOHN broke the window.(重读)","note":"口语常靠重读和语气强调,不一定动用整个 It is…that 框架"}]}'::jsonb, 'sufe');
